# Guarda el nombre del astronauta como cadena de texto (str)
nombre_astronauta = "Max"
# Guarda la edad del astronauta como número entero (int)
edad_astronauta = 25
# Guarda el planeta o lugar de destino como texto
destino = "Marte"
# Guarda el porcentaje de combustible restante como número entero
combustible = 85
# Guarda la velocidad de navegación como número entero
velocidad = 27000

# Imprime el título del diario y agrega un salto de línea extra (\n)
print("Diario de un Astronauta\n")

# Usa una f-string para insertar las variables de nombre, edad y destino dentro del texto
print(f"Hola, soy {nombre_astronauta}, tengo {edad_astronauta} años y mi próximo destino es {destino}.")
# Inserta velocidad, combustible y destino en el mensaje, y agrega un salto de línea al final (\n)
print(f"Estoy navegando a {velocidad} km/s con {combustible}% de combustible restante hacia {destino}.\n")

# Imprime la fecha de la primera entrada del diario
print("Fecha: 2024-01-10")
# Imprime el reporte de actividades del día
print("Hoy experimentamos con el cultivo de plantas en microgravedad.")
# Imprime la reflexión personal y añade un salto de línea adicional al final
print("Mensaje personal: ¡Es increíble ver cómo crecen las lechugas aquí arriba!\n")

